#define UNICODE
#include <windows.h>
void mainCRTStartup(void)
{
    static WCHAR environment[]=L"MIHAWK_ENV_ROOT=launch selected\0MIHAWK_ENV_UTF8=caf\x00e9 \x03a9\0MIHAWK_ENV_EMPTY=\0MIHAWK_ENV_CASE=last wins\0PATH=C:\\Selected Tools;C:\\windows\\system32\0\0";
    WCHAR command[2048];const WCHAR *p=GetCommandLineW();while(*p && *p!=' ')++p;while(*p==' ')++p;lstrcpyW(command,p);
    STARTUPINFOW startup={0};PROCESS_INFORMATION process={0};startup.cb=sizeof(startup);
    if(!CreateProcessW(NULL,command,NULL,NULL,FALSE,CREATE_UNICODE_ENVIRONMENT,environment,NULL,&startup,&process))ExitProcess(2);
    DWORD wait=WaitForSingleObject(process.hProcess,60000),code=~0u;
    if(wait!=WAIT_OBJECT_0) {TerminateProcess(process.hProcess,3);ExitProcess(3);}
    GetExitCodeProcess(process.hProcess,&code);CloseHandle(process.hThread);CloseHandle(process.hProcess);ExitProcess(code);
}
